DROP TABLE IF EXISTS tracks CASCADE;

DROP TABLE IF EXISTS metadata CASCADE;

DROP TABLE IF EXISTS track_authors CASCADE;

DROP TABLE IF EXISTS track_links CASCADE;

DROP TABLE IF EXISTS gpx_files CASCADE;

DROP TABLE IF EXISTS users CASCADE;


CREATE TABLE "tracks" (
  "id" UUID PRIMARY KEY,
  "name" varchar(120),
  "description" varchar (255),
  "type" varchar (120),
  "duration" time, private final JdbcTemplate jdbcTemplate;
  "complexity" varchar(120),
  "points" geometry(LineStringZ, 4326) NOT NULL
);

CREATE TABLE "metadata" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "track_id" UUID,
  "name" varchar(120),
  "author_id" bigint,
  "link_id" bigint
);

CREATE TABLE "track_authors" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" varchar(120)
);

CREATE TABLE "track_links" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "url" varchar(120)
);

CREATE TABLE "gpx_files" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "version" varchar(120),
  "creator" varchar(120),
  "schema_location" varchar(120),
  "metadata_id" bigint,
  "track_id" UUID
);

CREATE TABLE "users" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" varchar(120)
);

ALTER TABLE "metadata" ADD FOREIGN KEY ("author_id") REFERENCES "track_authors" ("id");
ALTER TABLE "metadata" ADD FOREIGN KEY ("link_id") REFERENCES "track_links" ("id");
ALTER TABLE "metadata" ADD FOREIGN KEY ("track_id") REFERENCES "tracks" ("id");
ALTER TABLE "gpx_files" ADD FOREIGN KEY ("metadata_id") REFERENCES "metadata" ("id");
ALTER TABLE "gpx_files" ADD FOREIGN KEY ("track_id") REFERENCES "tracks" ("id");